define([
    'jquery',
    'mage/translate',
    'mage/cookies',
    'Magento_Ui/js/modal/alert',
    'Magento_Ui/js/modal/confirm'
], function ($, $t, _cookies, alertModal, confirmModal) {
    'use strict';

    function showAlert(message)
    {
        alertModal({
            title: $t('B2B'),
            content: message
        });
    }

    function getFormKey()
    {
        if (window.FORM_KEY) {
            return window.FORM_KEY;
        }

        if ($.mage && $.mage.cookies) {
            return $.mage.cookies.get('form_key') || '';
        }

        return '';
    }

    return function (config, element) {
        var $root = $(element);
        var messages = config.messages || {};
        var qtyDebounceTimers = {};
        var qtyActiveRequests = {};
        var $recurringToggle = $root.find('[data-role="recurring-toggle"]');
        var $recurringOptions = $root.find('#recurring-options');
        var $liveRegion = $root.find('[data-role="shoppinglist-live"]').first();

        function announce(message)
        {
            if (!$liveRegion.length || !message) {
                return;
            }
            $liveRegion.text('');
            window.setTimeout(function () {
                $liveRegion.text(message);
            }, 10);
        }

        function setRecurringOptionsVisibility(isVisible)
        {
            $recurringOptions.toggleClass('recurring-options--collapsed', !isVisible);
            $recurringOptions.attr('aria-hidden', isVisible ? 'false' : 'true');
            $recurringToggle.attr('aria-expanded', isVisible ? 'true' : 'false');
            announce(
                isVisible
                    ? $t('Pedido recorrente ativado. Opções de recorrência exibidas.')
                    : $t('Pedido recorrente desativado.')
            );
        }

        $root.on('change', '[data-role="recurring-toggle"]', function () {
            setRecurringOptionsVisibility(this.checked);
        });

        $root.on('change', '.qty-input', function () {
            var $input = $(this);
            var itemId = parseInt($input.data('item-id'), 10) || 0;
            var updateUrl = $input.data('update-url') || '';
            var qty = parseInt($input.val(), 10) || 1;
            var timerKey = itemId > 0 ? String(itemId) : String(Date.now());

            if (!itemId || !updateUrl) {
                return;
            }

            qty = Math.max(1, qty);
            $input.val(qty);

            if (qtyActiveRequests[timerKey] && qtyActiveRequests[timerKey].readyState !== 4) {
                qtyActiveRequests[timerKey].abort();
            }

            clearTimeout(qtyDebounceTimers[timerKey]);
            qtyDebounceTimers[timerKey] = setTimeout(function () {
                $input.prop('disabled', true).attr('aria-busy', 'true');
                announce($t('Atualizando quantidade do item.'));
                qtyActiveRequests[timerKey] = $.ajax({
                    url: updateUrl,
                    type: 'POST',
                    dataType: 'json',
                    data: {
                        item_id: itemId,
                        qty: qty,
                        form_key: getFormKey()
                    },
                    showLoader: true
                }).done(function (response) {
                    if (response && response.success === false) {
                        announce(response.message || messages.qtyUpdateError || $t('Erro ao atualizar quantidade.'));
                        showAlert(response.message || messages.qtyUpdateError || $t('Erro ao atualizar quantidade.'));
                        return;
                    }
                    announce($t('Quantidade atualizada. Recarregando lista.'));
                    window.location.reload();
                }).fail(function (_xhr, status) {
                    if (status === 'abort') {
                        return;
                    }
                    announce(messages.qtyUpdateError || $t('Erro ao atualizar quantidade.'));
                    showAlert(messages.qtyUpdateError || $t('Erro ao atualizar quantidade.'));
                }).always(function () {
                    qtyActiveRequests[timerKey] = null;
                    $input.prop('disabled', false).removeAttr('aria-busy');
                });
            }, 450);
        });

        $root.on('click', '[data-confirm]', function (event) {
            var $trigger = $(this);
            var message = $trigger.data('confirm');
            var href = $trigger.attr('href');
            var targetFormId = String($trigger.data('target-form') || '');
            var $targetForm = targetFormId ? $('#' + targetFormId) : $();

            if (!message || (!$targetForm.length && !href)) {
                return;
            }

            event.preventDefault();
            confirmModal({
                title: $t('Confirmar'),
                content: message,
                actions: {
                    confirm: function () {
                        if ($targetForm.length) {
                            $targetForm.trigger('submit');
                            return;
                        }
                        window.location.href = href;
                    }
                }
            });
        });

        if ($recurringToggle.length && $recurringOptions.length) {
            setRecurringOptionsVisibility($recurringToggle.is(':checked'));
        }
    };
});
